CREATE TABLE IF NOT EXISTS guild_workspace_authority_state (
    StateKey INTEGER NOT NULL PRIMARY KEY CHECK(StateKey=1),
    InstallationGeneration TEXT NOT NULL CHECK(typeof(InstallationGeneration)='text' AND InstallationGeneration=upper(InstallationGeneration) AND length(InstallationGeneration)=36 AND substr(InstallationGeneration,9,1)='-' AND substr(InstallationGeneration,14,1)='-' AND substr(InstallationGeneration,19,1)='-' AND substr(InstallationGeneration,24,1)='-' AND length(replace(InstallationGeneration,'-',''))=32 AND replace(InstallationGeneration,'-','') NOT GLOB '*[^0-9A-F]*' AND InstallationGeneration<>'00000000-0000-0000-0000-000000000000'),
    NativeOperatorPrincipalId TEXT NOT NULL CHECK(typeof(NativeOperatorPrincipalId)='text' AND NativeOperatorPrincipalId=upper(NativeOperatorPrincipalId) AND length(NativeOperatorPrincipalId)=36 AND substr(NativeOperatorPrincipalId,9,1)='-' AND substr(NativeOperatorPrincipalId,14,1)='-' AND substr(NativeOperatorPrincipalId,19,1)='-' AND substr(NativeOperatorPrincipalId,24,1)='-' AND length(replace(NativeOperatorPrincipalId,'-',''))=32 AND replace(NativeOperatorPrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND NativeOperatorPrincipalId<>'00000000-0000-0000-0000-000000000000')
);
